# User Service Schema
type User @key(fields: "id") {
  id: ID!
  email: String!
  name: String!
  profile: Profile
  orders: [Order!]! @requires(fields: "id")
}

type Profile {
  bio: String
  avatar: String
  phone: String
}

extend type Query {
  user(id: ID!): User
  users(limit: Int = 20): [User!]!
}

# Order Service Schema
type Order @key(fields: "id") {
  id: ID!
  total: Float!
  status: OrderStatus!
  user: User! @provides(fields: "id")
  items: [OrderItem!]!
}

enum OrderStatus {
  PENDING
  CONFIRMED
  SHIPPED
  DELIVERED
}

import { ApolloGateway, IntrospectAndCompose } from '@apollo/gateway';
import { ApolloServer } from 'apollo-server';

const gateway = new ApolloGateway({
  supergraphSdl: new IntrospectAndCompose({
    subgraphs: [
      { name: 'users', url: 'http://users-service:4001/graphql' },
      { name: 'orders', url: 'http://orders-service:4002/graphql' },
      { name: 'products', url: 'http://products-service:4003/graphql' },
      { name: 'payments', url: 'http://payments-service:4004/graphql' }
    ]
  }),
  buildService({ url }) {
    return new RemoteGraphQLDataSource({
      url,
      willSendRequest({ request, context }) {
        request.http.headers.set('user-id', context.userId);
      }
    });
  }
});

const server = new ApolloServer({ gateway });

