const client = new ApolloClient({
  uri: 'https://api.company.com/graphql',
  cache: new InMemoryCache({
    typePolicies: {
      Query: {
        fields: {
          users: {
            merge(existing, incoming) {
              return incoming;
            }
          }
        }
      }
    }
  })
});

