import { buildFederatedSchema } from '@apollo/federation';
import DataLoader from 'dataloader';

const userLoader = new DataLoader(async (ids) => {
  const users = await db.users.findMany({ where: { id: { in: ids } } });
  return ids.map(id => users.find(u => u.id === id));
});

const resolvers = {
  Query: {
    user: (_, { id }, context) => context.loaders.user.load(id),
    users: (_, { limit }, context) => db.users.findMany({ take: limit })
  },
  User: {
    __resolveReference: (user, context) => {
      return context.loaders.user.load(user.id);
    },
    orders: (user, _, context) => {
      return context.loaders.ordersByUser.load(user.id);
    }
  }
};

export const schema = buildFederatedSchema([{ typeDefs, resolvers }]);

