CREATE PROCEDURE GetUserOrders
  @UserId INT
AS
BEGIN
  SELECT u.*, o.*, oi.*, p.*
  FROM Users u
  LEFT JOIN Orders o ON u.Id = o.UserId
  LEFT JOIN OrderItems oi ON o.Id = oi.OrderId
  LEFT JOIN Products p ON oi.ProductId = p.Id
  WHERE u.Id = @UserId
END

